__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"privacy",{enumerable:!0,get:function(){return o}});const o={pt:{title:'Privacidade e suporte',updated:'Vers\xe3o 1.1.0 \xb7 Atualizado em 27 de outubro de 2026',sections:[['Quem somos','AI Engineering Lab \xe9 um aplicativo educacional da Eniglio Tech Press, de Eduardo Niglio. Contato: enigliotechpress@gmail.com.'],['Aprendizado independente','O app oferece 24 desafios de engenharia de IA, justificativas e uma nota de estudo. N\xe3o \xe9 necess\xe1rio comprar o livro, criar conta ou enviar uma avalia\xe7\xe3o. Os cen\xe1rios s\xe3o did\xe1ticos; o app n\xe3o executa modelos de IA nem emite certifica\xe7\xe3o profissional.'],['Dados no aparelho','Idioma, respostas, progresso e posi\xe7\xe3o no carrossel ficam no armazenamento local do app. Reiniciar o quiz apaga respostas e progresso locais. Desinstalar o app remove seus dados locais, sujeito \xe0s configura\xe7\xf5es de backup do sistema. N\xe3o h\xe1 sincroniza\xe7\xe3o de progresso com nosso servidor.'],['Envio opcional de avalia\xe7\xe3o','Somente quando voc\xea toca em Enviar por e-mail, o app transmite as estrelas, o coment\xe1rio opcional, a quantidade de acertos, o total de desafios e o idioma para a equipe. Esses dados s\xe3o usados para receber sua opini\xe3o e melhorar o conte\xfado. N\xe3o envie informa\xe7\xf5es pessoais, confidenciais ou sens\xedveis no coment\xe1rio. A avalia\xe7\xe3o n\xe3o \xe9 publicada nem enviada \xe0s avalia\xe7\xf5es da loja.'],['Servi\xe7os que processam o envio','O envio passa pelo Cloudflare Worker e pelo Google Apps Script/Gmail at\xe9 enigliotechpress@gmail.com. Como em qualquer conex\xe3o \xe0 internet, os provedores processam o endere\xe7o IP e informa\xe7\xf5es t\xe9cnicas da requisi\xe7\xe3o para entrega e prote\xe7\xe3o contra abuso. N\xe3o inclu\xedmos IP no e-mail de avalia\xe7\xe3o. Esses provedores podem processar dados fora do Brasil, conforme suas pol\xedticas.'],['Sem localiza\xe7\xe3o ou rastreamento','Esta vers\xe3o n\xe3o solicita nem coleta localiza\xe7\xe3o, contatos, c\xe2mera, microfone ou identificador de publicidade. N\xe3o envia aviso autom\xe1tico de primeira abertura, n\xe3o usa an\xfancios e n\xe3o registra um token de notifica\xe7\xf5es. N\xe3o vendemos dados nem os usamos para publicidade direcionada.'],['Conserva\xe7\xe3o e exclus\xe3o','As avalia\xe7\xf5es enviadas permanecem na caixa de e-mail da equipe enquanto forem necess\xe1rias para atendimento e melhoria do app; esta vers\xe3o n\xe3o implementa exclus\xe3o autom\xe1tica desses e-mails. Para solicitar acesso, corre\xe7\xe3o ou exclus\xe3o de uma mensagem, escreva ao contato acima e informe a data aproximada e um trecho do coment\xe1rio para identific\xe1-la. Reiniciar o quiz n\xe3o apaga e-mails j\xe1 enviados. Registros t\xe9cnicos dos provedores seguem suas pr\xf3prias configura\xe7\xf5es e pol\xedticas.'],['Suas escolhas','Voc\xea pode usar todos os desafios sem enviar dados \xe0 equipe. N\xe3o h\xe1 login, assinatura ou compra dentro do app. Links para site e redes sociais s\xe3o opcionais e abrem servi\xe7os externos, que possuem pol\xedticas pr\xf3prias. O conte\xfado \xe9 voltado a estudantes e profissionais de tecnologia; n\xe3o \xe9 destinado especificamente a crian\xe7as.'],['Ajuda e altera\xe7\xf5es','Para relatar um problema, envie a vers\xe3o do app, o modelo do aparelho e uma descri\xe7\xe3o a enigliotechpress@gmail.com, sem senhas ou outros dados sens\xedveis. Se o tratamento de dados mudar, atualizaremos esta pol\xedtica e as informa\xe7\xf5es das lojas antes de distribuir a altera\xe7\xe3o.']]},en:{title:'Privacy and support',updated:'Version 1.1.0 \xb7 Updated October 27, 2026',sections:[['Who we are','AI Engineering Lab is an educational app by Eniglio Tech Press, Eduardo Niglio. Contact: enigliotechpress@gmail.com.'],['Independent learning','The app offers 24 AI engineering challenges, explanations and a study score. No book purchase, account or feedback submission is required. Scenarios are educational; the app does not run AI models or issue professional certification.'],['On-device data','Language, answers, progress and carousel position are stored locally. Restarting the quiz clears local answers and progress. Uninstalling removes local app data, subject to system backup settings. Progress is not synchronized with our server.'],['Optional feedback','Only when you tap Send by email does the app transmit your star rating, optional comment, correct-answer count, challenge total and language to the team. These are used to receive feedback and improve the content. Do not include personal, confidential or sensitive information. Feedback is not published or submitted as a store review.'],['Delivery services','Submission passes through a Cloudflare Worker and Google Apps Script/Gmail to enigliotechpress@gmail.com. As with any internet connection, these providers process the IP address and technical request information for delivery and abuse prevention. We do not include your IP in the feedback email. Providers may process data internationally under their own policies.'],['No location or tracking','This version does not request or collect location, contacts, camera, microphone or advertising identifiers. It does not send an automatic first-open event, display ads or register a notification token. We do not sell data or use it for targeted advertising.'],['Retention and deletion','Submitted feedback remains in the team mailbox while needed for support and app improvements; this version does not automatically delete those emails. To request access, correction or deletion, contact us with the approximate date and an excerpt that helps identify the message. Restarting the quiz does not delete submitted emails. Provider technical records follow their own settings and policies.'],['Your choices','All challenges work without submitting feedback. There is no login, subscription or in-app purchase. Website and social links are optional and open external services with their own policies. Content is intended for technology students and professionals and is not specifically directed at children.'],['Support and changes','To report an issue, email the app version, device model and a description to enigliotechpress@gmail.com without passwords or sensitive information. If data practices change, we will update this policy and store disclosures before distributing the change.']]}}},771,[]);